def solve_detailed(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    T = {}
    for k in range(n + 1):
        T[k] = 0

    for p in perms:
        inv = 0
        for i in range(n):
            for j in range(i + 1, n):
                if p[i] > p[j]:
                    inv += 1
        sigma = 1 if inv % 2 == 0 else -1

        fixed_points = 0
        for i in range(n):
            if p[i] == i + 1:
                fixed_points += 1

        T[fixed_points] += sigma

    total_sum = 0
    for k in range(n + 1):
        total_sum += T[k] / (k + 1)

    return T, total_sum

for n in range(1, 7):
