import itertools

def get_cycle_types(n):
    def get_partitions(n, min_val=1):
        if n == 0:
            yield []
            return
        for i in range(min_val, n + 1):
            for p in get_partitions(n - i, i):
                yield [i] + p

    partitions = list(get_partitions(n))
    results = []
    for p in partitions:
        # Number of permutations with cycle type p
        # formula: n! / (prod(k^c_k) * prod(c_k!))
        counts = {}
        for x in p:
            counts[x] = counts.get(x, 0) + 1

        denom = 1
        for k, c in counts.items():
            denom *= (k**c) * (factorial(c))

        num = factorial(n)
        count = num // denom

        # Sign: (-1)^(n - number of cycles)
        sign = 1 if (n - len(p)) % 2 == 0 else -1
        # Number of fixed points: number of 1s in the partition
        fixed_points = p.count(1)
        results.append((p, count, sign, fixed_points))
    return results

def factorial(n):
    res = 1
    for i in range(2, n + 1):
        res *= i
    return res

