def get_d_values(n_max):
    d = [0] * (n_max + 1)
    # d_m = sum_{pi in D_m} sigma(pi)
    # We can use the property P_m(x) = sum_{k=0}^m binom(m, k) d_{m-k} x^k
    # Also P_m(x) = sum_{pi in S_m} sigma(pi) x^{v(pi)}
    # Let's just compute d_m directly for small m
    for m in range(n_max + 1):
        # Find all permutations of {0, ..., m-1}
        perms = list(itertools.permutations(range(m)))
        sum_sigma = 0
        for p in perms:
            # Check if derangement
            is_derangement = True
            for i in range(m):
                if p[i] == i:
                    is_derangement = False
                    break
            if is_derangement:
                # Calculate sign
                sign = 1
                visited = [False] * m
                for i in range(m):
                    if not visited[i]:
                        count = 0
                        curr = i
                        while not visited[curr]:
                            visited[curr] = True
                            curr = p[curr]
                            count += 1
                        if count % 2 == 0:
                            sign *= -1
                sum_sigma += sign
        d[m] = sum_sigma
    return d

